import{_ as p,a0 as t,w as c,s as o,ao as d,I as l,x as s,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 ACL 設置用户訪問指定文件/目錄的權限 | LCTT x X-CMD","titleTemplate":false,"description":"使用 ACL 設置用户訪問指定文件/目錄的權限 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 ACL 設置用户訪問指定文件/目錄的權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 ACL 設置用户訪問指定文件/目錄的權限 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL","title":"使用 ACL 設置用户訪問指定文件/目錄的權限","tag":"201801","desc":""},"relativePath":"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL.md","filePath":"[post].md"}'),r={name:"201801/20171213 How To Allow-Permit User To Access A Specific File or Folder In Linux Using ACL.md"};function h(g,a,k,b,u,f){const e=t("Link");return c(),o("div",null,[a[13]||(a[13]=d(`<h1 id="使用-acl-設置用户訪問指定文件-目錄的權限" tabindex="-1">使用 ACL 設置用户訪問指定文件/目錄的權限 <a class="header-anchor" href="#使用-acl-設置用户訪問指定文件-目錄的權限" aria-label="Permalink to “使用 ACL 設置用户訪問指定文件/目錄的權限”">​</a></h1><p>當提到文件和目錄的權限時，你的第一反應可能是“屬主/羣組/其它”權限。 這些權限可以通過 <code>chmod</code>、 <code>chown</code> 等命令來修改。</p><p>文件和目錄都有屬主 (文件所有者 )、羣組 (所屬組) 以及其它權限，這些權限構成一個集合。 然而這些權限集合有它的侷限性，無法做到為不同的用户設置不同的權限。</p><p>Linux 對文件和目錄有以下默認權限。</p><ul><li>文件 -&gt; <code>644</code> -&gt; <code>-rw-r-r-</code> （所有者有讀寫權限，組成員有隻讀權限， 其他人也只有讀權限）</li><li>目錄 -&gt; <code>755</code> -&gt; <code>drwxr-xr-x</code> （所有者有讀、寫和執行權限，組成員有讀和執行的權限，其他人也有讀和執行的權限）</li></ul><p>比如： 默認情況下，所有者可以訪問和編輯他們自己主目錄中的文件， 也可以訪問相關同組人的文件，但他們不能修改這些文件，因為組成員沒有寫權限，而且讓組成員有寫權限也是不明智的。 基於同樣的原因，他/她也不能修改其他人的文件。 然而在某些情況下，多個用户想要修改同一個文件， 那該怎麼辦呢？</p><p>假設有個名叫 <code>magi</code> 的用户，他想要修改 <code>httpd.conf</code> 文件怎麼辦呢？ 這個文件是歸 root 用户所有的，這樣如何授權呢？ 為了解決這種情況，<ruby>訪問控制列表<rt>Access Control List</rt></ruby>（ACL）誕生了。</p><h3 id="什麼是-acl" tabindex="-1">什麼是 ACL？ <a class="header-anchor" href="#什麼是-acl" aria-label="Permalink to “什麼是 ACL？”">​</a></h3><p>ACL 表示<ruby>訪問控制列表<rt>Access Control List</rt></ruby>（ACL），它為文件系統提供了附加的、更具有彈性的權限機制。 它被設計來為補充 UNIX 文件權限機制。 ACL 允許你賦予任何某用户/組訪問某項資源的權限。 <code>setfacl</code> 與 <code>getfacl</code> 命令會幫助你管理 ACL 而不會有任何麻煩。</p><h3 id="什麼是-setfacl" tabindex="-1">什麼是 setfacl？ <a class="header-anchor" href="#什麼是-setfacl" aria-label="Permalink to “什麼是 setfacl？”">​</a></h3><p><code>setfacl</code> 用於設置文件和目錄的 ACL。</p><h3 id="什麼-getfacl" tabindex="-1">什麼 getfacl？ <a class="header-anchor" href="#什麼-getfacl" aria-label="Permalink to “什麼 getfacl？”">​</a></h3><p><code>getfacl</code> - 獲取文件的 ACL 。對於每個文件， <code>getfacl</code> 都會顯示文件名、文件所有者、所屬組以及ACL。 如果目錄有默認 ACL， <code>getfacl</code> 也會顯示這個默認的 ACL。</p><h3 id="如何確認是否啓用了-acl" tabindex="-1">如何確認是否啓用了 ACL？ <a class="header-anchor" href="#如何確認是否啓用了-acl" aria-label="Permalink to “如何確認是否啓用了 ACL？”">​</a></h3><p>運行 <code>tune2fs</code> 命令來檢查是否啓用了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -l /dev/sdb1 | grep options</span></span>
<span class="line"><span>Default mount options: (none)</span></span></code></pre></div><p>上面的輸出很明顯第説明 <code>/dev/sdb1</code> 分區沒有啓用 ACL。</p><p>如果結果中沒有列出 <code>acl</code>，則你需要在掛載選項中加上 <code>acl</code>。 為了讓它永久生效， 修改 <code>/etc/fstab</code> 中 <code>/app</code> 這一行成這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># more /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UUID=f304277d-1063-40a2-b9dc-8bcf30466a03 / ext4 defaults 1 1</span></span>
<span class="line"><span>/dev/sdb1 		 /app ext4 defaults，acl 1 1</span></span></code></pre></div><p>或者，你也可以使用下面命令將其添加道文件系統的超級塊中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -o +acl /dev/sdb1</span></span></code></pre></div><p>現在，通過運行以下命令來動態修改選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -o remount,acl /app</span></span></code></pre></div><p>再次運行 <code>tune2fs</code> 命令來看選項中是否有 <code>acl</code> 了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tune2fs -l /dev/sdb1 | grep options</span></span>
<span class="line"><span>Default mount options： acl</span></span></code></pre></div><p>嗯，現在 <code>/dev/sdb1</code> 分區中有 ACL 選項了。</p><h3 id="如何查看默認的-acl-值" tabindex="-1">如何查看默認的 ACL 值 <a class="header-anchor" href="#如何查看默認的-acl-值" aria-label="Permalink to “如何查看默認的 ACL 值”">​</a></h3><p>要查看文件和目錄默認的 ACL 值，可以使用 <code>getfacl</code> 命令後面加上文件路徑或者目錄路徑。 注意， 當你對非 ACL 文件/目錄運行 <code>getfacl</code> 命令時， 則不會顯示附加的 <code>user</code> 和 <code>mask</code> 參數值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><h3 id="如何為文件設置-acl" tabindex="-1">如何為文件設置 ACL <a class="header-anchor" href="#如何為文件設置-acl" aria-label="Permalink to “如何為文件設置 ACL”">​</a></h3><p>以下面格式運行 <code>setfacl</code> 命令可以為指定文件設置 ACL。在下面的例子中，我們會給 <code>magi</code> 用户對 <code>/etc/apache2/apache2.conf</code> 文件 <code>rwx</code> 的權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m u:magi:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>仔細分析起來：</strong></p><ul><li><code>setfacl</code>： 命令</li><li><code>-m</code>： 修改文件的當前 ACL</li><li><code>u</code>： 指明用户</li><li><code>magi</code>： 用户名</li><li><code>rwx</code>： 要設置的權限</li><li><code>/etc/apache2/apache2.conf</code>： 文件名稱</li></ul><p>再查看一次新的 ACL 值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>user:magi:rwx</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>mask::rwx</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><p>注意： 若你發現文件或目錄權限後面有一個加號（<code>+</code>），就表示設置了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -lh /etc/apache2/apache2.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 7.1K Sep 19 14:58 /etc/apache2/apache2.conf</span></span></code></pre></div><h3 id="如何為目錄設置-acl" tabindex="-1">如何為目錄設置 ACL <a class="header-anchor" href="#如何為目錄設置-acl" aria-label="Permalink to “如何為目錄設置 ACL”">​</a></h3><p>以下面格式運行 <code>setfacl</code> 命令可以遞歸地為指定目錄設置 ACL。在下面的例子中，我們會將 <code>/etc/apache2/sites-available/</code> 目錄中的 <code>rwx</code> 權限賦予 <code>magi</code> 用户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -Rm u:magi:rwx /etc/apache2/sites-available/</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-R</code>： 遞歸到子目錄中</li></ul><p>再次查看一下新的 ACL 值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/sites-available/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/sites-available/</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rwx</span></span>
<span class="line"><span>user:magi:rwx</span></span>
<span class="line"><span>group::r-x</span></span>
<span class="line"><span>mask::rwx</span></span>
<span class="line"><span>other::r-x</span></span></code></pre></div><p>現在 <code>/etc/apache2/sites-available/</code> 中的文件和目錄都設置了 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -lh /etc/apache2/sites-available/</span></span>
<span class="line"><span>total 20K</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Sep 19 14:56 000-default.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 6.2K Sep 19 14:56 default-ssl.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Dec 8 02:57 mywebpage.com.conf</span></span>
<span class="line"><span>-rw-rwxr--+ 1 root root 1.4K Dec 7 19:07 testpage.com.conf</span></span></code></pre></div><h3 id="如何為組設置-acl" tabindex="-1">如何為組設置 ACL <a class="header-anchor" href="#如何為組設置-acl" aria-label="Permalink to “如何為組設置 ACL”">​</a></h3><p>以下面格式為指定文件運行 <code>setfacl</code> 命令。在下面的例子中，我們會給 <code>appdev</code> 組賦予 <code>/etc/apache2/apache2.conf</code> 文件的 <code>rwx</code> 權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m g:appdev:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>g</code>： 指明一個組</li></ul><p>對多個用户和組授權，只需要用 <code>逗號</code> 區分開，就像下面這樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -m u:magi:rwx,g:appdev:rwx /etc/apache2/apache2.conf</span></span></code></pre></div><h3 id="如何刪除-acl" tabindex="-1">如何刪除 ACL <a class="header-anchor" href="#如何刪除-acl" aria-label="Permalink to “如何刪除 ACL”">​</a></h3><p>以下面格式運行 <code>setfacl</code> 命令會刪除文件對指定用户的 ACL。這隻會刪除用户權限而保留 <code>mask</code> 的值為只讀。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -x u:magi /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-x</code>： 從文件的 ACL 中刪除</li></ul><p>再次查看 ACL 值。在下面的輸出中我們可以看到 <code>mask</code> 的值是讀。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>mask::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><p>使用 <code>-b</code> 來刪除文件中所有的 ACL。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl -b /etc/apache2/apache2.conf</span></span></code></pre></div><p><strong>其中：</strong></p><ul><li><code>-b</code>： 刪除所有的 ACL 條目</li></ul><p>再次查看刪掉後的 ACl 值就會發現所有的東西都不見了，包括 <code>mask</code> 的值也不見了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># getfacl /etc/apache2/apache2.conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># file： etc/apache2/apache2.conf</span></span>
<span class="line"><span># owner： root</span></span>
<span class="line"><span># group： root</span></span>
<span class="line"><span>user::rw-</span></span>
<span class="line"><span>group::r--</span></span>
<span class="line"><span>other::r--</span></span></code></pre></div><h3 id="如何備份並還原-acl" tabindex="-1">如何備份並還原 ACL <a class="header-anchor" href="#如何備份並還原-acl" aria-label="Permalink to “如何備份並還原 ACL”">​</a></h3><p>下面命令可以備份和還原 ACL 的值。要製作備份， 需要進入對應的目錄然後這樣做（假設我們要備份 <code>sites-available</code> 目錄中的 ACL 值)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /etc/apache2/sites-available/</span></span>
<span class="line"><span># getfacl -R * &gt; acl_backup_for_folder</span></span></code></pre></div><p>還原的話，則運行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># setfacl --restore=/etc/apache2/sites-available/acl_backup_for_folder</span></span></code></pre></div><hr>`,73)),l("p",null,[a[1]||(a[1]=s("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-configure-access-control-lists-acls-setfacl-getfacl-linux/"},{default:i(()=>[...a[0]||(a[0]=[s("https://www.2daygeek.com/how-to-configure-access-control-lists-acls-setfacl-getfacl-linux/",-1)])]),_:1})]),l("p",null,[a[5]||(a[5]=s("作者：",-1)),n(e,{href:"https://www.2daygeek.com"},{default:i(()=>[...a[2]||(a[2]=[s("MAGESH MARUTHAMUTHU",-1)])]),_:1}),a[6]||(a[6]=s(" 譯者：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[7]||(a[7]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[10]||(a[10]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[s("Linux中國",-1)])]),_:1}),a[12]||(a[12]=s(" 榮譽推出",-1))])])}const A=p(r,[["render",h]]);export{x as __pageData,A as default};
